<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, RouterLink } from 'vue-router'; import { api, type Category, type Source } from '../api'; import { statusLabel, useI18n } from '../i18n'
const { t } = useI18n(); const route = useRoute(); const category = ref<Category>(); const sources = ref<Source[]>([]); const loading = ref(true); const query = ref(''); const status = ref(''); const filtered = computed(() => sources.value.filter(x => (!query.value || `${x.name} ${x.base_url}`.toLowerCase().includes(query.value.toLowerCase())) && (!status.value || x.status === status.value)))
function shortName(name: string) { return name.length > 24 ? `${name.slice(0, 23)}…` : name }
onMounted(async () => { try { const cats = await api<Category[]>('/public/categories'); category.value = cats.find(x => x.slug === route.params.category); sources.value = await api<Source[]>(`/public/sources?category=${encodeURIComponent(String(route.params.category))}`) } finally { loading.value = false } })
</script>
<template><main class="page category-page"><section class="subhero compact-subhero"><div><p class="eyebrow">REGISTRY CATEGORY</p><h1>{{ category?.name || route.params.category }}</h1><p>{{ category?.description || t.sources }}</p></div><div class="page-counter"><strong>{{ filtered.length }}</strong><span>/ {{ sources.length }} {{ t.sources }}</span></div></section><section class="panel directory-panel"><div class="directory-toolbar"><label class="search-box"><span>⌕</span><input v-model="query" :placeholder="t.search"></label><select v-model="status"><option value="">{{ t.status }}: {{ t.all }}</option><option value="online">{{ t.online }}</option><option value="degraded">{{ t.degraded }}</option><option value="offline">{{ t.offline }}</option></select></div><div class="category-table-head"><span></span><span>{{ t.registry }}</span><span>{{ t.url }}</span><span>{{ t.response }}</span><span>{{ t.status }}</span></div><div v-if="loading" class="empty">{{ t.loading }}</div><div v-else-if="!filtered.length" class="empty">{{ t.noResults }}</div><div v-for="source in filtered" :key="source.id" class="source"><span class="status-dot" :class="source.status"></span><div class="source-main"><RouterLink :to="`/source/${source.id}`" :title="source.name"><strong>{{ shortName(source.name) }}</strong></RouterLink></div><a class="source-url" :href="source.base_url" target="_blank" rel="noopener noreferrer">{{ source.base_url }}</a><div class="response"><strong>{{ source.response_ms ? `${source.response_ms} ms` : t.unknown }}</strong></div><div class="state" :class="source.status">{{ statusLabel(source.status, t) }}</div></div></section></main></template>
